INSERT INTO releases (version, released_on, title, public_notes, tech_notes) VALUES (
  '2.97.0',
  '2026-09-23',
  'Пульт ТВ: заставка и титры настраиваются в админке',
  E'Кнопка «Пропустить» теперь настраивается по-человечески. В админке у сериала появилась «✂»: выбираете сезон, потом серию — и она играет прямо там. Доводите до нужного места, жмёте «Заставка начинается», потом «Заставка кончается» — и так же для титров. Шаги ±1, ±10 и ±60 секунд помогают попасть точно.\n\nОтметку можно записать на весь сериал, на один сезон или только на эту серию: где отмечено точнее, то и играет. Если после титров идёт ещё сцена, отметьте «Титры кончаются» — тогда «Пропустить» приведёт к ней, а не к следующей серии; если после титров ничего нет, есть кнопка «Титры до конца серии».\n\nА ещё тайминги часто записаны в самом файле: у mkv бывают главы «Opening» и «Ending Credits». Кнопка «Взять из глав файла» ставит отметки сама.',
  E'media-agent: marks.go переписан на три уровня. marksScopes = {series, season, episode}, у каждого ключ (хеш пути) и сам путь; merged() идёт от общего к частному, заставка и титры наследуются порознь (intro копируется при intro_end > 0, титры — при credits_from_end > 0). PUT /api/marks принимает scope (series по умолчанию; season у фильма — 400). Новое поле credits_end_from_end (тоже от конца файла): 0 — титры до самого конца, иначе после них сцена. Если уточняют один край, а второй записан уровнем выше, недостающий доносится из merged — иначе запись не прошла бы проверку и пропала. moveMarks() ведёт записи за переименованием (вызов в renamePath рядом с moveProgress); путь «сериала» берётся по o.key, а не как o.dir, иначе у фильма в корне библиотеки запись не переезжала.\n\nplayer.html: в админке редактор — видео живёт вне #adbody (перерисовки его не прерывают), список сезонов и серий через /api/browse, транспорт ⏯ и ±1/10/60 с, кнопки отметок берут currentTime (титры — duration − currentTime), выбор уровня, сброс своего уровня и сводка по всем трём. Та же панель под видео в плеере получила конец титров и выбор уровня. В timeupdate: при отмеченном конце титров показывается «⏭ Пропустить титры» (kind after-credits) и прыжок к сцене вместо отсчёта следующей серии.\n\nGET /api/marks/chapters?file= — ffprobe -show_chapters: глава из первой четверти серии с «intro|opening|заставк» становится заставкой, из последней трети с «credit|ending|титр» — титрами, следующая за ними глава даёт конец титров. Общей базы таймингов в интернете нет: AniSkip покрывает только аниме и ищет по id MyAnimeList, у Jellyfin это локальное сравнение звуковых отпечатков соседних серий — записано в BACKLOG.\n\nПроверено в браузере на локальном агенте: отметки всех трёх уровней и их наследование, сброс уровня, фильм одним файлом (у него «сериал» и «серия» — одна запись, второй уровень скрыт), переходы по «Назад», «Взять из глав файла» на mkv с главами (0:10–0:40 и титры за 0:20 с концом за 0:05), пропуск заставки, отсчёт следующей серии и прыжок к сцене после титров.'
);
-- +goose StatementEnd

-- +goose Down
DELETE FROM releases WHERE version = '2.97.0';
